            'cc_eyebrow' => 'CALCULADORA DE COSTO DE SPREAD FOREX',
            'cc_intro' => 'Estima tu costo anual de spread EUR/USD en cada uno de nuestros brókers investigados con un spread confirmado, según tu propio patrón de trading -- no una cifra genérica de "nuestro spread promedio".',
