            'cc_label_holding_period' => 'Periodo de mantenimiento típico',
            'cc_overnight_strong' => 'El financiamiento overnight no está incluido en esta estimación.',
            'cc_overnight_body' => 'Dado que tu periodo de mantenimiento seleccionado implica mantener posiciones durante la noche, los cargos de swap/financiamiento se añadirán a tu costo real. Las tasas de swap varían según el bróker, según la dirección (largo vs. corto), y cambian diariamente con las tasas de referencia -- están documentadas como notas de investigación en la página de reseña de cada bróker, no como una cifra única comparable que pudiéramos multiplicar aquí con confianza. Revisa la sección "Financiamiento overnight" en la página de reseña de un bróker antes de operar con un periodo de mantenimiento de varios días.',
            'cc_results_label' => 'Costo anual estimado, el más económico primero',
            'cc_results_of' => 'de',
            'cc_results_suffix' => 'brókers investigados',
            'cc_disclaimer_p1' => '%1$s de nuestros %2$s brókers investigados no tienen un spread EUR/USD confirmado de forma independiente y están excluidos de esta comparación por completo, en lugar de asumirse como gratis o promedio.',
            'cc_disclaimer_p2' => 'Esta estimación cubre %s -- la comisión de ida y vuelta, común en cuentas tipo ECN/Razor, es un costo adicional real documentado en notas de investigación de texto libre por bróker, no como una cifra estructurada que pudiéramos promediar con confianza, por lo que no se cuenta aquí.',
            'cc_spread_cost_only' => 'solo el costo de spread',
            'cc_disclaimer_p3' => 'Un bróker con el spread más bajo mostrado no es necesariamente el costo real más bajo una vez incluida su comisión -- revisa la sección "Modelo de ejecución" en la página de reseña de ese bróker.',
            'cc_formula_label' => 'Fórmula:',
