            'rc_read_full_review_link' => 'Leer la reseña completa del bróker →',
            'rc_disclaimer' => 'Cada cifra aquí se remonta a los mismos datos investigados detrás de la página de reseña de este bróker y nuestras clasificaciones -- nada mostrado aquí se puntúa o calcula de forma diferente para esta herramienta. Cada código de regulador actualmente en nuestros datos se ha resuelto a una geografía específica, verificada contra las propias divulgaciones regulatorias de cada bróker (ver inc/regulation-checker.php para saber exactamente qué evidencia resolvió cada uno) -- pero si añadimos un bróker cuyo código de regulador no se haya verificado así todavía, mostramos el código como investigado y dejamos la geografía sin especificar en lugar de adivinar. Verifica siempre el estado actual de la licencia directamente en el registro público propio del regulador antes de depositar fondos -- los enlaces de arriba van al registro oficial de cada regulador o a su página de inicio, no a una búsqueda prellenada específica del bróker.',
