            'cl_eyebrow' => 'REGISTRO DE CAMBIOS DE BRÓKERS',
            'cl_intro' => 'Busca cualquiera de nuestros brókers investigados para ver un registro fechado de cuándo nuestros datos publicados sobre él cambiaron realmente -- una actualización de spread, un nuevo número de licencia, una plataforma añadida o eliminada.',
            'cl_what_this_is_strong' => 'Qué es esto, y qué no es.',
            'cl_what_this_is_body' => 'Cada entrada aquí proviene de que los propios datos de este sitio se comparan con lo publicado anteriormente, fechada en el momento en que se detectó esa diferencia -- nunca una historia reconstruida de lo que el bróker mismo hizo antes de que empezáramos a rastrear. Un bróker que muestra solo una única entrada "Registro base" simplemente no ha tenido un cambio en un campo rastreado desde que comenzó este registro; no es una señal de que nunca haya cambiado nada sobre ese bróker.',
            'cl_get_notified_strong' => 'Recibe un aviso cuando algo realmente cambie.',
            'cl_get_notified_body' => 'Suscríbete abajo y te enviaremos un correo solo cuando este registro anote un cambio genuino en un dato rastreado (una actualización de spread, un nuevo número de licencia, una plataforma añadida o eliminada) en cualquier bróker que cubrimos -- nunca un boletín genérico, y nunca más de un correo por cada cambio que detectemos. Cancela la suscripción en cualquier momento con el enlace en ese correo.',
