            'sec_rankings_p' => 'Echte, derzeit bei CySEC, FCA oder der Seychellen-FSA lizenzierte Broker, bewertet mit einer offengelegten, auf öffentlichen Daten basierenden Methodik -- nicht mit praktischen Tests. Siehe „Wie wir bewerten" unten.',
            'sec_method_h2' => 'Wie wir Broker bewerten',
