            'method1_h3' => 'Regulierung & Kundenschutz',
            'method1_p' => 'Ein fester Punktwert für jeden unabhängig überprüfbaren gehaltenen Regulierer (CySEC, die FCA, ASIC und ähnliche Tier-1/Tier-2-Stellen), gemessen an einer offengelegten Skala -- kein Vergleich zu anderen Brokern. Eine reine Offshore-Lizenz, wie die Seychellen-FSA, bringt für sich allein nichts: Sie spiegelt eine wesentlich leichtere Aufsicht und kein gesetzliches Anlegerentschädigungssystem wider, obwohl wir diese Lizenz und ihre Nummer weiterhin auf der Testbericht-Seite des Brokers offenlegen.',
            'method2_h3' => 'Handelskosten',
            'method2_p' => 'Der EUR/USD-Spread des Brokers gegenüber festen Pip-Schwellenwerten. Wir gewichten den Mindesteinzahlungsbetrag hier bewusst nicht -- ein Broker, der Sie mit 1.000 $ starten lässt, verlangt Ihnen nicht mehr fürs Handeln ab als einer, der Sie mit 10 $ starten lässt.',
            'method3_h3' => 'Nicht handelsbezogene Gebühren',
            'method3_p' => 'Bestätigte Inaktivitätsgebühren und Währungsumrechnungsgebühren. Ein Broker, der bestätigt keine von beiden erhebt, schneidet gut ab; einer mit einer bestätigten Gebühr schneidet schlechter ab; wo wir es in keiner Richtung unabhängig bestätigen konnten, liegt dieser Faktor an einem neutralen Mittelpunkt, statt geschätzt zu werden.',
            'method4_h3' => 'Plattformen & Tools',
            'method4_p' => 'Anzahl der unterstützten unterschiedlichen Handelsplattformen (MT4, MT5, cTrader, TradingView, proprietär). Dies ist eine Breitenzählung, kein Qualitätsurteil einer einzelnen Plattform -- weshalb es auch weniger Gewicht trägt als früher.',
            'method5_h3' => 'Ausführung / Handelsbedingungen',
            'method5_p' => 'Ob der Broker ein No-Dealing-Desk-Ausführungsmodell (ECN/STP/DMA) offenlegt, abgewertet bei jedem unabhängig berichteten Muster von Auszahlungsverweigerungen, Fondsmanipulation oder ähnlichen in unserer Recherche gefundenen Verhaltens-Warnsignalen.',
            'method6_h3' => 'Produktpalette',
            'method6_p' => 'Wie viele unterschiedliche Anlageklassen (Forex, Indizes, Aktien, Rohstoffe, Krypto, Anleihen, ETFs und mehr) wir unabhängig bestätigen konnten, dass der Broker anbietet, gemessen an einer festen Skala.',
            'method7_h3' => 'Ein- & Auszahlungen',
            'method7_p' => 'Bestätigte Ein-/Auszahlungsgebühren und Bearbeitungsgeschwindigkeit, abgewertet bei jedem unabhängig berichteten Muster von verzögerten, blockierten oder angefochtenen Auszahlungen.',
            'method8_h3' => 'Transparenz',
            'method8_p' => 'Startet unbelastet und wird nur für spezifische, benannte Befunde aus unserer Recherche abgewertet: eine Regulierer-Warnung oder Blacklisting, ein bestätigtes Klon-/Identitätsdiebstahlrisiko, bestätigte Bewertungsmanipulation, oder ein nicht mehr aktiver/abgewickelter Status.',
