            'cc_eyebrow' => 'FOREX-SPREAD-KOSTENRECHNER',
            'cc_intro' => 'Schätzen Sie Ihre jährlichen EUR/USD-Spread-Kosten bei jedem unserer untersuchten Broker mit einem bestätigten Spread, basierend auf Ihrem eigenen Handelsmuster -- keine generische „unser durchschnittlicher Spread"-Zahl.',
