            'cc_hint_lot_sizes' => '1,0 = Standardlot (100.000 Einheiten), 0,1 = Minilot, 0,01 = Mikrolot.',
            'cc_label_holding_period' => 'Typische Haltedauer',
            'cc_overnight_strong' => 'Overnight-Finanzierung ist in dieser Schätzung nicht enthalten.',
            'cc_overnight_body' => 'Da Ihre gewählte Haltedauer das Halten von Positionen über Nacht beinhaltet, erhöhen Swap-/Finanzierungsgebühren Ihre tatsächlichen Kosten. Swapsätze variieren je nach Broker, je nach Richtung (long vs. short) und ändern sich täglich mit den Referenzzinssätzen -- sie sind als Rechercheanmerkungen auf der Testbericht-Seite jedes Brokers dokumentiert, nicht als eine einzige vergleichbare Zahl, die wir hier mit Zuversicht multiplizieren könnten. Prüfen Sie den Abschnitt „Overnight-Finanzierung" auf der Testbericht-Seite eines Brokers, bevor Sie mit einer mehrtägigen Haltedauer handeln.',
            'cc_results_label' => 'Geschätzte Jahreskosten, günstigste zuerst',
