            'cc_disclaimer_p2' => 'Diese Schätzung umfasst %s -- die Round-Turn-Kommission, üblich bei ECN/Razor-Konten, ist eine reale zusätzliche Kostenart, die in freitextlichen Rechercheanmerkungen pro Broker dokumentiert ist, nicht als strukturierte Zahl, die wir mit Zuversicht durchschnittlich berechnen könnten, daher wird sie hier nicht mitgezählt.',
            'cc_spread_cost_only' => 'nur die Spread-Kosten',
            'cc_disclaimer_p3' => 'Ein Broker mit dem niedrigsten angezeigten Spread ist nicht unbedingt der mit den niedrigsten tatsächlichen Kosten, sobald seine Kommission einbezogen wird -- prüfen Sie den Abschnitt „Ausführungsmodell" auf der Testbericht-Seite dieses Brokers.',
            'cc_formula_label' => 'Formel:',
