            'rc_read_full_review_link' => 'Den vollständigen Broker-Testbericht lesen →',
            'rc_disclaimer' => 'Jede Zahl hier geht auf dieselben untersuchten Daten zurück, die der Testbericht-Seite dieses Brokers und unseren Ranglisten zugrunde liegen -- nichts hier wird für dieses Tool anders bewertet oder berechnet. Jeder Regulierer-Code, der derzeit in unseren Daten vorkommt, wurde einer bestimmten Geografie zugeordnet und gegen die eigenen regulatorischen Angaben jedes Brokers verifiziert (siehe inc/regulation-checker.php für genau die Belege, die jeden einzelnen auflösten) -- fügen wir jedoch einen Broker hinzu, dessen Regulierer-Code noch nicht so geprüft wurde, zeigen wir den Code als untersucht und lassen die Geografie unangegeben, statt zu raten. Überprüfen Sie den aktuellen Lizenzstatus stets direkt im eigenen öffentlichen Register des Regulierers, bevor Sie Geld einzahlen -- die obigen Links führen zum offiziellen Register oder zur Landingpage jedes Regulierers, nicht zu einer brokerspezifisch vorausgefüllten Suche.',
