            'cl_eyebrow' => 'BROKER-ÄNDERUNGSPROTOKOLL',
            'cl_intro' => 'Durchsuchen Sie unsere untersuchten Broker nach einem datierten Protokoll, wann sich unsere veröffentlichten Daten über ihn tatsächlich geändert haben -- eine Spread-Aktualisierung, eine neue Lizenznummer, eine hinzugefügte oder entfernte Plattform.',
            'cl_what_this_is_strong' => 'Was dies ist, und was nicht.',
            'cl_what_this_is_body' => 'Jeder Eintrag hier stammt daraus, dass die eigenen Daten dieser Website mit dem zuvor Veröffentlichten verglichen werden, datiert auf den Zeitpunkt, an dem dieser Unterschied festgestellt wurde -- niemals eine rekonstruierte Geschichte dessen, was der Broker selbst getan hat, bevor wir mit der Verfolgung begannen. Ein Broker, der nur einen einzigen Eintrag „Basiswert erfasst" zeigt, hatte einfach seit Beginn dieses Protokolls keine Änderung in einem verfolgten Feld; das ist kein Zeichen dafür, dass sich bei diesem Broker nie etwas geändert hat.',
            'cl_get_notified_strong' => 'Lassen Sie sich benachrichtigen, wenn sich tatsächlich etwas ändert.',
            'cl_get_notified_body' => 'Abonnieren Sie unten, und wir schicken Ihnen nur eine E-Mail, wenn dieses Protokoll eine echte Änderung an einer verfolgten Tatsache (eine Spread-Aktualisierung, eine neue Lizenznummer, eine hinzugefügte oder entfernte Plattform) bei einem der von uns abgedeckten Broker verzeichnet -- niemals ein allgemeiner Newsletter, und niemals mehr als eine E-Mail pro festgestellter Änderung. Melden Sie sich jederzeit über den Link in dieser E-Mail ab.',
            'cl_msg_subscribed' => 'Sie sind angemeldet -- wir schicken Ihnen nur eine E-Mail, wenn sich eine verfolgte Broker-Tatsache tatsächlich ändert.',
