            'sec_countries_p' => 'يختلف التنظيم والوسطاء المتاحون كثيرًا حسب مكان إقامتك -- ابدأ من هنا.',
            'method1_h3' => 'التنظيم وحماية العميل',
            'method1_p' => 'قيمة نقاط ثابتة لكل جهة تنظيمية يمكن التحقق منها بشكل مستقل (CySEC، وFCA، وASIC، وهيئات مماثلة من الفئة الأولى/الثانية)، وفق مقياس معلن -- لا مقارنة مع وسطاء آخرين. ترخيص بحري (offshore) فقط، مثل هيئة سيشل FSA، لا يضيف شيئًا بمفرده: فهو يعكس إشرافًا أخف بشكل كبير وعدم وجود نظام تعويض نظامي للمستثمرين، مع أننا نواصل الإفشاء عن هذا الترخيص ورقمه في صفحة مراجعة الوسيط.',
            'method2_h3' => 'تكاليف التداول',
            'method2_p' => 'فرق السعر (سبريد) لليورو/الدولار لدى الوسيط مقارنة بعتبات نقاط ثابتة. نتعمد عدم ترجيح الحد الأدنى للإيداع هنا -- فالوسيط الذي يتيح لك البدء بـ 1,000 دولار لا يتقاضى منك أكثر مقابل التداول من وسيط يتيح لك البدء بـ 10 دولارات.',
            'method3_h3' => 'رسوم غير متعلقة بالتداول',
            'method3_p' => 'رسوم عدم النشاط المؤكدة ورسوم تحويل العملات. الوسيط المؤكد عدم تحصيله لأي منها يحصل على تقييم جيد؛ والوسيط ذو الرسم المؤكد يحصل على تقييم أضعف؛ وحيث لم نتمكن من التأكيد المستقل بأي اتجاه، يبقى هذا العامل عند نقطة وسطى محايدة بدل التخمين.',
            'method4_h3' => 'المنصات والأدوات',
            'method4_p' => 'عدد منصات التداول المختلفة المدعومة (MT4، MT5، cTrader، TradingView، منصة خاصة). هذا عدّ لمدى التنوع، لا حكم جودة لأي منصة بعينها -- وهذا أيضًا سبب انخفاض وزنه عما كان عليه.',
            'method5_h3' => 'التنفيذ / شروط التداول',
            'method5_p' => 'ما إذا كان الوسيط يُفشي عن نموذج تنفيذ بلا مكتب تداول (ECN/STP/DMA)، مع خصم عند وجود أي نمط مُبلَّغ عنه بشكل مستقل من رفض السحوبات، أو التلاعب بالأموال، أو إشارات تحذيرية سلوكية مشابهة وجدناها في بحثنا.',
            'method6_h3' => 'تنوع المنتجات',
            'method6_p' => 'عدد فئات الأصول المختلفة (الفوركس، المؤشرات، الأسهم، السلع، العملات المشفرة، السندات، صناديق المؤشرات المتداولة، وغيرها) التي تمكّنا من تأكيد تقديم الوسيط لها بشكل مستقل، وفق مقياس ثابت.',
            'method7_h3' => 'الإيداعات والسحوبات',
            'method7_p' => 'رسوم الإيداع/السحب المؤكدة وسرعة المعالجة، مع خصم عند وجود أي نمط مُبلَّغ عنه بشكل مستقل من السحوبات المتأخرة أو المحجوبة أو المتنازع عليها.',
            'method8_h3' => 'الشفافية',
