            'rev_external_reviews_intro' => 'تقييمات كما وُجدت من خلال المحتوى المنشور/المفهرس لكل موقع، وليست من اختبارنا الخاص ولم تُعاد التحقق منها بشكل مستقل مقابل الصفحة المباشرة -- تعامل معها كلقطة لحظية وتحقق من المصدر قبل الاعتماد عليها. لا نجمع هذه التقييمات في متوسط واحد مدمج: فكل موقع يقيس أشياء مختلفة بمقاييس مختلفة (بعضها تقييمات شعور المستخدمين، وأخرى صيغ ثقة من مزودي الخدمة)، لذا فإن حساب المتوسط سيعطي انطباعًا بقابلية مقارنة غير موجودة حقًا. تربط كل بطاقة بالمكان الذي وجدناها فيه -- اقرأها كل على حدة وفق سياقها الخاص.',
