            'cc_overnight_strong' => 'التمويل الليلي غير مشمول في هذا التقدير.',
            'cc_overnight_body' => 'بما أن فترة الاحتفاظ التي اخترتها تتضمن الاحتفاظ بمراكز بين عشية وضحاها، فإن رسوم السواب/التمويل ستُضاف إلى تكلفتك الفعلية. تختلف معدلات السواب حسب الوسيط، وحسب الاتجاه (شراء مقابل بيع)، وتتغير يوميًا مع أسعار المرجع -- وهي موثّقة كملاحظات بحثية في صفحة مراجعة كل وسيط، وليست كرقم واحد قابل للمقارنة يمكننا ضربه هنا بثقة. راجع قسم "التمويل الليلي" في صفحة مراجعة الوسيط قبل التداول بفترة احتفاظ متعددة الأيام.',
