            'cc_results_suffix' => 'وسيطًا مبحوثًا',
            'cc_disclaimer_p1' => 'لا يملك %1$s من بين %2$s وسيطًا مبحوثًا لدينا سبريد يورو/دولار مؤكدًا بشكل مستقل، وهم مستثنون تمامًا من هذه المقارنة، بدلًا من افتراض أنهم مجانيون أو متوسطون.',
            'cc_disclaimer_p2' => 'يغطي هذا التقدير %s -- العمولة ذهابًا وعودة، الشائعة في الحسابات من نوع ECN/Razor، هي تكلفة إضافية حقيقية موثّقة في ملاحظات بحثية نصية حرة لكل وسيط، وليست كرقم مُهيكل يمكننا حساب متوسطه بثقة، لذا لا تُحسب هنا.',
            'cc_spread_cost_only' => 'تكلفة السبريد فقط',
