            'rc_disclaimer' => 'كل رقم هنا يعود إلى نفس البيانات المبحوثة التي تقوم عليها صفحة مراجعة هذا الوسيط وتصنيفاتنا -- لا شيء معروض هنا يُقيَّم أو يُحسب بشكل مختلف لهذه الأداة. تم تحديد كل رمز جهة تنظيمية موجود حاليًا في بياناتنا إلى منطقة جغرافية محددة، تم التحقق منها مقابل إفصاحات الوسيط التنظيمية الخاصة (راجع inc/regulation-checker.php لمعرفة الدليل الذي حدد كل واحد بالضبط) -- ولكن إذا أضفنا وسيطًا لم يُفحص رمز جهته التنظيمية بهذه الطريقة بعد، نعرض الرمز كما بحث ونترك المنطقة الجغرافية غير محددة بدلًا من التخمين. تحقق دائمًا من حالة الترخيص الحالية مباشرة في السجل العام الخاص بالجهة التنظيمية قبل إيداع الأموال -- الروابط أعلاه تؤدي إلى السجل الرسمي لكل جهة تنظيمية أو صفحتها الرئيسية، وليس بحثًا مُعدًّا مسبقًا خاصًا بوسيط معين.',
