            'cl_what_this_is_strong' => 'ما هذا، وما ليس هذا.',
            'cl_what_this_is_body' => 'كل إدخال هنا ينشأ من مقارنة بيانات هذا الموقع الخاصة بما كان منشورًا سابقًا، ومؤرَّخ بوقت اكتشاف ذلك الاختلاف -- وليس أبدًا تاريخًا معاد بناؤه لما فعله الوسيط نفسه قبل أن نبدأ التتبع. الوسيط الذي يُظهر إدخالًا واحدًا فقط بعنوان "تم تسجيل خط الأساس" لم يطرأ عليه مجرد تغيير في حقل متتبَّع منذ بدء هذا السجل؛ وهذا ليس علامة على أن شيئًا لم يتغيَّر أبدًا بشأن ذلك الوسيط.',
            'cl_get_notified_strong' => 'احصل على إشعار عندما يتغيّر شيء فعليًا.',
            'cl_get_notified_body' => 'اشترك أدناه، وسنرسل لك بريدًا إلكترونيًا فقط عندما يسجّل هذا السجل تغييرًا حقيقيًا في حقيقة متتبَّعة (تحديث سبريد، رقم ترخيص جديد، منصة أُضيفت أو أُزيلت) لدى أي وسيط نغطيه -- ليست نشرة إخبارية عامة أبدًا، وليس أكثر من بريد إلكتروني واحد لكل تغيير نكتشفه. ألغِ الاشتراك في أي وقت عبر الرابط في ذلك البريد الإلكتروني.',
