            'tb_methodology_how_calculated' => 'Comment cette note est calculée :',
            'tb_methodology_note_body' => "Neuf catégories pondérées selon un référentiel fixe et divulgué -- réglementation et protection du client 30 %, coûts de trading 20 %, frais hors trading 10 %, plateformes et outils 10 %, exécution/conditions de trading 10 %, gamme de produits 5 %, dépôts/retraits 5 %, transparence 5 %, antériorité 5 % -- ce n'est pas un classement relatif par rapport aux autres courtiers, ni un test pratique de compte.",
