            'rev_external_reviews_h2' => 'Ce que disent les autres évaluateurs',
            'rev_external_reviews_intro' => "Notes telles que trouvées via le contenu publié/indexé de chaque site, pas issues de nos propres tests et non re-vérifiées de manière indépendante sur la page en direct -- à considérer comme un instantané ; vérifiez la source avant de vous y fier. Nous ne les combinons pas en une seule moyenne globale : chaque site mesure des choses différentes sur des échelles différentes (certaines sont des notes de sentiment des utilisateurs, d'autres des formules de score de confiance des fournisseurs), donc en faire une moyenne impliquerait une comparabilité qui n'existe pas réellement. Chaque carte renvoie à l'endroit où nous l'avons trouvée -- lisez-les individuellement, selon leurs propres termes.",
