            'rc_disclaimer' => "Chaque chiffre ici remonte aux mêmes données étudiées qui sous-tendent la page d'avis de ce courtier et nos classements -- rien affiché ici n'est noté ou calculé différemment pour cet outil. Chaque code de régulateur actuellement dans nos données a été résolu à une zone géographique spécifique, vérifiée par rapport aux propres divulgations réglementaires de chaque courtier (voir inc/regulation-checker.php pour savoir exactement quelle preuve a résolu chacun) -- mais si nous ajoutons un courtier dont le code de régulateur n'a pas encore été vérifié ainsi, nous affichons le code comme étudié et laissons la zone géographique non précisée plutôt que de deviner. Vérifiez toujours le statut actuel de la licence directement sur le registre public propre du régulateur avant de déposer des fonds -- les liens ci-dessus mènent au registre officiel de chaque régulateur ou à sa page d'accueil, pas à une recherche pré-remplie spécifique à un courtier.",
