            'cl_eyebrow' => 'JOURNAL DES MODIFICATIONS DU COURTIER',
            'cl_intro' => "Recherchez n'importe lequel de nos courtiers étudiés pour voir un journal daté des moments où nos données publiées à son sujet ont réellement changé -- une mise à jour de spread, un nouveau numéro de licence, une plateforme ajoutée ou retirée.",
            'cl_what_this_is_strong' => "Ce que c'est, et ce que ce n'est pas.",
            'cl_what_this_is_body' => "Chaque entrée ici provient de la comparaison des propres données de ce site avec ce qui était publié précédemment, datée du moment où cette différence a été détectée -- jamais un historique reconstruit de ce que le courtier lui-même a fait avant que nous ne commencions le suivi. Un courtier n'affichant qu'une seule entrée « Référence enregistrée » n'a simplement pas eu de changement dans un champ suivi depuis le début de ce journal ; ce n'est pas un signe que rien n'a jamais changé chez ce courtier.",
