            'method1_p' => 'Stała wartość punktowa za każdego niezależnie weryfikowalnego regulatora (CySEC, FCA, ASIC i podobne organy Tier-1/Tier-2), według jawnej skali -- nie w porównaniu z innymi brokerami. Licencja wyłącznie offshore, jak seszelska FSA, sama w sobie nic nie dodaje: odzwierciedla znacznie lżejszy nadzór i brak ustawowego systemu rekompensat dla inwestorów, choć wciąż ujawniamy tę licencję i jej numer na stronie recenzji brokera.',
            'method2_h3' => 'Koszty tradingu',
            'method2_p' => 'Spread EUR/USD brokera względem stałych progów pipsowych. Celowo nie ważymy tu minimalnego depozytu -- broker pozwalający zacząć od 1000 USD nie pobiera wyższych kosztów handlu niż ten pozwalający zacząć od 10 USD.',
            'method3_h3' => 'Opłaty niezwiązane z tradingiem',
            'method3_p' => 'Potwierdzone opłaty za nieaktywność i przewalutowanie. Broker potwierdzony jako niepobierający żadnej z nich ocenia się dobrze; broker z potwierdzoną opłatą ocenia się słabiej; gdzie nie mogliśmy niezależnie potwierdzić w żadną stronę, ten czynnik przyjmuje neutralną wartość środkową, a nie jest zgadywany.',
            'method4_h3' => 'Platformy i narzędzia',
            'method4_p' => 'Liczba obsługiwanych odrębnych platform tradingowych (MT4, MT5, cTrader, TradingView, własna). To liczenie zakresu, a nie ocena jakości konkretnej platformy -- co jest też powodem, dla którego ma mniejszą wagę niż dawniej.',
            'method5_h3' => 'Egzekucja / warunki tradingu',
            'method5_p' => 'Czy broker ujawnia model egzekucji bez biurka dealerskiego (ECN/STP/DMA), z obniżką za jakikolwiek niezależnie zgłoszony wzorzec odmów wypłat, manipulacji środkami lub podobnych sygnałów ostrzegawczych znalezionych w naszych badaniach.',
            'method6_h3' => 'Zakres produktów',
            'method6_p' => 'Ile odrębnych klas aktywów (forex, indeksy, akcje, surowce, krypto, obligacje, ETF i więcej) mogliśmy niezależnie potwierdzić, że broker oferuje, według stałej skali.',
            'method7_h3' => 'Depozyty i wypłaty',
            'method7_p' => 'Potwierdzone opłaty za depozyty/wypłaty i szybkość przetwarzania, z obniżką za jakikolwiek niezależnie zgłoszony wzorzec opóźnionych, zablokowanych lub spornych wypłat.',
            'method8_h3' => 'Przejrzystość',
            'method8_p' => 'Zaczyna bez obniżek i jest obniżana tylko za konkretne, nazwane ustalenia z naszych badań: ostrzeżenie lub umieszczenie na czarnej liście przez regulatora, potwierdzone ryzyko klonowania/podszywania się, potwierdzoną manipulację recenzjami, lub status zamknięcia/likwidacji działalności.',
            'method9_h3' => 'Historia działania',
            'method9_p' => 'Lata działalności, według stałej skali od roku założenia. Brokerzy działający dłużej otrzymują wyższą ocenę.',
