            'rev_external_reviews_h2' => 'Co mówią inni recenzenci',
            'rev_external_reviews_intro' => 'Oceny znalezione w opublikowanej/zindeksowanej treści każdej witryny, a nie z naszych własnych testów i nie zweryfikowane ponownie niezależnie na żywej stronie -- traktuj jako zrzut stanu i sprawdź źródło, zanim na nim polegasz. Nie łączymy ich w jedną uśrednioną wartość: każda witryna mierzy inne rzeczy na innych skalach (niektóre to oceny nastrojów użytkowników, inne to formuły ocen zaufania dostawców), więc uśrednianie sugerowałoby porównywalność, której w rzeczywistości nie ma. Każda karta linkuje do miejsca, w którym ją znaleźliśmy -- przeczytaj je indywidualnie, na ich własnych warunkach.',
