            'hero1_p' => 'Valutiamo ogni broker in nove categorie ponderate -- regolamentazione, costi, commissioni, piattaforme, esecuzione, gamma di prodotti, depositi/prelievi, trasparenza e track record -- secondo una griglia fissa e divulgata, costruita a partire da documenti normativi e informative dei broker, non da test pratici sul conto.',
            'hero_search_label' => 'RICERCA RAPIDA BROKER', 'hero_search_placeholder' => 'Cerca un broker per nome…', 'hero_search_button' => 'Cerca',
            'hero2_eyebrow' => 'NOVITÀ DI QUESTO MESE', 'hero2_h1' => 'Segui il mercato con la nostra mappa di calore in tempo reale.',
            'hero2_p' => 'Scopri quali coppie di valute, metalli e mercati energetici si stanno muovendo in questo momento, e come si confrontano gli spread dei broker per ciascuno.',
            'hero2_button' => 'Vedi la panoramica del mercato',
            'hero3_eyebrow' => 'FORMAZIONE GRATUITA', 'hero3_h1' => 'Nuovo nel trading? Inizia dalle basi.',
            'hero3_p' => 'Guide in italiano semplice su forex, materie prime, petrolio e oro -- senza gergo tecnico, senza proposte di vendita.',
            'hero3_button' => 'Esplora le guide',
            'trust1' => 'Broker regolamentati analizzati', 'trust2' => 'Fattori di valutazione, interamente divulgati',
            'trust3' => 'Guide e articoli educativi gratuiti', 'trust4' => 'Finanziato dalle classifiche dei broker',
            'sec_overview_h2' => 'Panoramica del mercato',
            'sec_overview_p' => "Un'istantanea dei mercati forex, metalli ed energia di oggi. Aggiornata durante tutta la giornata di trading.",
            'sec_heatmap_h3' => 'Mappa di calore del mercato', 'sec_movers_h3' => 'I movimenti di oggi',
            'sec_blog_h2' => 'Dal blog', 'sec_blog_p' => 'Spiegazioni in italiano semplice su come funzionano realmente i mercati forex e delle materie prime.',
            'sec_news_h2' => 'Ultime notizie',
            'sec_news_p' => 'Sviluppi specifici sui broker e analisi originali del mercato FX -- non una riproduzione massiva di titoli da agenzie di stampa.',
            'sec_rankings_h2' => 'Top 15 broker forex regolamentati',
            'sec_rankings_p' => 'Broker reali, attualmente autorizzati da CySEC, FCA o dalla FSA delle Seychelles, valutati con una metodologia divulgata basata su dati pubblici -- non su test pratici. Vedi "Come valutiamo" di seguito.',
            'sec_method_h2' => 'Come valutiamo i broker',
            'sec_method_p' => 'Questa è una metodologia divulgata e basata sui dati -- non una dichiarazione di test pratici sul conto. Ecco esattamente come viene costruito ogni punteggio.',
            'sec_guides_h2' => 'Guide per il tuo stile di trading',
            'sec_guides_p' => 'Inizia da dove sei -- nuovo nel forex, in fase di cambio piattaforma, oppure in ottimizzazione dei costi.',
            'sec_compare_h2' => 'Confronta i broker testa a testa',
            'sec_compare_p' => 'Metti due broker fianco a fianco su costi, piattaforme e regolamentazione.',
            'sec_countries_h2' => 'Migliori broker per paese',
            'sec_countries_p' => 'La regolamentazione e i broker disponibili variano molto in base a dove vivi -- inizia da qui.',
            'method1_h3' => 'Regolamentazione e protezione del cliente',
            'method1_p' => "Un valore in punti fisso per ogni regolatore verificabile in modo indipendente detenuto (CySEC, la FCA, l'ASIC e organismi simili di livello Tier-1/Tier-2), secondo una scala divulgata -- non un confronto con altri broker. Una licenza solo offshore, come la FSA delle Seychelles, non aggiunge nulla di per sé: riflette una supervisione notevolmente più leggera e nessuno schema statutario di compensazione per gli investitori, sebbene continuiamo a divulgare quella licenza e il suo numero nella pagina di recensione del broker.",
            'method2_h3' => 'Costi di trading',
            'method2_p' => 'Lo spread EUR/USD del broker rispetto a soglie fisse in pip. Deliberatamente non pesiamo qui il deposito minimo -- un broker che ti lascia iniziare con 1.000$ non ti fa pagare di più per fare trading rispetto a uno che ti lascia iniziare con 10$.',
            'method3_h3' => 'Commissioni non di trading',
            'method3_p' => 'Commissioni di inattività e spese di conversione valutaria confermate. Un broker confermato non applicare nessuna delle due ottiene un buon punteggio; uno con una commissione confermata ottiene un punteggio peggiore; dove non abbiamo potuto confermare in modo indipendente in alcun senso, questo fattore si colloca su un punto medio neutrale piuttosto che essere indovinato.',
            'method4_h3' => 'Piattaforme e strumenti',
            'method4_p' => 'Numero di piattaforme di trading distinte supportate (MT4, MT5, cTrader, TradingView, proprietaria). Questo è un conteggio di ampiezza, non un giudizio di qualità di una singola piattaforma -- motivo per cui ha anche meno peso rispetto a prima.',
            'method5_h3' => 'Esecuzione / condizioni di trading',
            'method5_p' => 'Se il broker divulga un modello di esecuzione senza desk di negoziazione (ECN/STP/DMA), scontato per qualsiasi schema segnalato in modo indipendente di rifiuti di prelievo, manipolazione di fondi, o segnali di allarme comportamentali simili trovati nella nostra ricerca.',
            'method6_h3' => 'Gamma di prodotti',
            'method6_p' => 'Quante classi di attività distinte (forex, indici, azioni, materie prime, cripto, obbligazioni, ETF e altro) abbiamo potuto confermare in modo indipendente che il broker offre, secondo una scala fissa.',
            'method7_h3' => 'Depositi e prelievi',
            'method7_p' => 'Commissioni di deposito/prelievo confermate e velocità di elaborazione, scontate per qualsiasi schema segnalato in modo indipendente di prelievi ritardati, bloccati o contestati.',
            'method8_h3' => 'Trasparenza',
            'method8_p' => 'Parte senza penalità ed è scontata solo per riscontri specifici e nominati dalla nostra ricerca: un avvertimento o inserimento in blacklist da un regolatore, un rischio confermato di clone/impersonazione, manipolazione confermata delle recensioni, o uno stato di cessazione/liquidazione.',
            'method9_h3' => 'Track record',
            'method9_p' => "Anni di operatività, secondo una scala fissa dall'anno di fondazione. I broker in attività da più tempo ottengono un punteggio più alto.",
