            'cc_disclaimer_p2' => 'Questa stima copre %s -- la commissione round-turn, comune sui conti di tipo ECN/Razor, è un costo aggiuntivo reale documentato in note di ricerca in testo libero per broker, non come un numero strutturato che potremmo mediare con sicurezza, quindi non è contata qui.',
