            'sec_guides_h2' => 'Guias para o seu estilo de trading',
            'sec_guides_p' => 'Comece de onde você estiver -- novo no forex, trocando de plataforma, ou otimizando custos.',
            'sec_compare_h2' => 'Compare corretoras lado a lado',
            'sec_compare_p' => 'Coloque duas corretoras lado a lado em custo, plataformas e regulação.',
            'sec_countries_h2' => 'Melhores corretoras por país',
            'sec_countries_p' => 'A regulação e as corretoras disponíveis variam muito de acordo com onde você mora -- comece aqui.',
            'method1_h3' => 'Regulação e proteção ao cliente',
            'method1_p' => 'Um valor fixo de pontos para cada regulador verificável de forma independente mantido (CySEC, a FCA, a ASIC e órgãos semelhantes de Nível 1/2), segundo uma escala divulgada -- não uma comparação com outras corretoras. Uma licença apenas offshore, como a FSA das Seicheles, não agrega nada por si só: reflete uma supervisão significativamente mais leve e nenhum esquema estatutário de compensação ao investidor, embora ainda divulguemos essa licença e seu número na página de avaliação da corretora.',
            'method2_h3' => 'Custos de trading',
            'method2_p' => 'O spread EUR/USD da corretora em relação a limites fixos em pips. Deliberadamente não ponderamos o depósito mínimo aqui -- uma corretora que permite começar com US$ 1.000 não cobra mais para negociar do que uma que permite começar com US$ 10.',
            'method3_h3' => 'Taxas não relacionadas ao trading',
            'method3_p' => 'Taxas de inatividade e cobranças de conversão de moeda confirmadas. Uma corretora confirmada como não cobrando nenhuma das duas pontua bem; uma com taxa confirmada pontua pior; onde não pudemos confirmar de forma independente em nenhum sentido, este fator fica em um ponto médio neutro em vez de ser adivinhado.',
            'method4_h3' => 'Plataformas e ferramentas',
            'method4_p' => 'Número de plataformas de trading distintas suportadas (MT4, MT5, cTrader, TradingView, proprietária). Esta é uma contagem de amplitude, não um julgamento de qualidade de qualquer plataforma específica -- razão pela qual também tem menos peso do que antes.',
            'method5_h3' => 'Execução / condições de trading',
            'method5_p' => 'Se a corretora divulga um modelo de execução sem mesa de operações (ECN/STP/DMA), descontado por qualquer padrão relatado de forma independente de recusas de retirada, manipulação de fundos, ou sinais de alerta de conduta semelhantes encontrados em nossa pesquisa.',
            'method6_h3' => 'Variedade de produtos',
            'method6_p' => 'Quantas classes de ativos distintas (forex, índices, ações, commodities, cripto, títulos, ETFs e mais) conseguimos confirmar de forma independente que a corretora oferece, segundo uma escala fixa.',
            'method7_h3' => 'Depósitos e retiradas',
            'method7_p' => 'Taxas de depósito/retirada confirmadas e velocidade de processamento, descontadas por qualquer padrão relatado de forma independente de retiradas atrasadas, bloqueadas ou contestadas.',
            'method8_h3' => 'Transparência',
            'method8_p' => 'Começa limpa e é descontada apenas por constatações específicas e nomeadas de nossa pesquisa: um alerta ou inclusão em lista negra por um regulador, um risco confirmado de clone/falsificação, manipulação confirmada de avaliações, ou um status de encerramento/liquidação.',
            'method9_h3' => 'Histórico',
            'method9_p' => 'Anos em operação, segundo uma escala fixa a partir do ano de fundação. Corretoras em operação há mais tempo pontuam mais alto.',
