            'rev_external_reviews_intro' => 'Classificações conforme encontradas no conteúdo publicado/indexado de cada site, não a partir de nossos próprios testes e não reverificadas de forma independente na página ativa -- trate como um retrato momentâneo e verifique a fonte antes de confiar nela. Não as combinamos em uma média única: cada site mede coisas diferentes em escalas diferentes (algumas são avaliações de sentimento do usuário, outras fórmulas de pontuação de confiança do fornecedor), então calcular uma média implicaria uma comparabilidade que realmente não existe. Cada cartão aponta para onde a encontramos -- leia-as individualmente, nos seus próprios termos.',
